//! FFmpeg bindings generated by scripts/generate-bindings.ps1, plus the macros bindgen cannot see.

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals, dead_code, clippy::all)]

mod bindings;

pub use bindings::*;

/// `AV_NOPTS_VALUE`
pub const NO_PTS: i64 = i64::MIN;
/// `AVERROR(EAGAIN)`: 11 is `EAGAIN` in the MSVC runtime FFmpeg's Windows ABI uses.
pub const AVERROR_EAGAIN: i32 = -11;
/// `AVERROR_EOF`, that is `FFERRTAG('E', 'O', 'F', ' ')`.
pub const AVERROR_EOF: i32 = -(0x45 | (0x4f << 8) | (0x46 << 16) | (0x20 << 24));
